<script setup lang="ts">import{onBeforeUnmount,onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['JobProgress'][]>([]);let timer:number|undefined;async function refresh(){values.value=requireData(await client.GET('/api/admin/jobs'))}onMounted(()=>{void refresh();timer=window.setInterval(refresh,3000)});onBeforeUnmount(()=>clearInterval(timer))</script>
<template><PageHeader title="后台任务"/><div class="grid gap-3"><article v-for="value in values" :key="`${value.kind}:${value.subjectId}`" class="rounded-card border border-border p-4"><strong>{{ value.kind }}</strong><p class="text-sm text-muted">{{ value.subjectId }} · {{ value.state }}</p><progress :value="value.percent" max="100" class="w-full"/></article><p v-if="!values.length" class="text-muted">当前没有任务。</p></div></template>
